// ════════════════════════════════════════════════════════════════
//  СИСТЕМА БАЗОВЫХ ФОРМУЛ СТИХИЙ
//  Базовая формула (ранг D) — едина для всех заклинаний данной стихии.
//  Остальные ранги получают процентную надбавку к базовой формуле.
//
//  Логика (по требованию пользователя):
//    D  = базовая (0%)
//    DD = базовая + 10%   (промежуточный)
//    C  = базовая + 20%
//    CC = базовая + 30%   (промежуточный)
//    B  = базовая + 40%
//    BB = базовая + 50%   (промежуточный)
//    A  = базовая + 60%
//    AA = базовая + 70%   (промежуточный)
//    S  = базовая + 80%
//    SS = базовая + 90%   (промежуточный)
//
//  Итоговая формула заклинания:
//    - Если у заклинания есть собственное поле `formula` (непустое) — оно перекрывает стихийную.
//    - Иначе: baseFormula × (1 + rankPercent/100), показывается как строка.
// ════════════════════════════════════════════════════════════════

// Список стихий (магические стихии + типы оружия, которые есть в DB_SPELLS)
export const SPELL_ELEMENTS = [
  '🔥 Огонь',
  '❄️ Лёд',
  '🌊 Вода',
  '🌪️ Воздух',
  '🗿 Земля',
  '🌑 Тьма',
  '🌞 Свет',
  '🧪 Яд',
  '🌀 Призыв',
  '🌌 Хаос',
  '✨Иллюзия',
  '🌐Телепортация',
  // Типы оружия (есть в DB_SPELLS как element)
  '⚔️Кинжалы',
  '🛡️🗡️Одноручное оружие + Щит',
  '🔱Копье',
  '🗡️Двуручное оружие',
  '🏹Лук',
  'посох',
];

// Список рангов по порядку
export const SPELL_RANKS = ['D', 'DD', 'C', 'CC', 'B', 'BB', 'A', 'AA', 'S', 'SS'];

// Проценты надбавки по рангам (D=база, S=+80%)
export const DEFAULT_RANK_PERCENTS = {
  D: 0, DD: 10, C: 20, CC: 30, B: 40, BB: 50, A: 60, AA: 70, S: 80, SS: 90,
};

// Базовые формулы по умолчанию для каждой стихии.
// Пользователь может отредактировать их в админке (вкладка «Формулы стихий»).
// Структура: { [element]: { baseFormula: string, rankPercents: { D, DD, C, CC, B, BB, A, AA, S, SS } } }
export const DEFAULT_SPELL_FORMULAS = SPELL_ELEMENTS.reduce((acc, element) => {
  acc[element] = {
    baseFormula: 'M*0,12*((crit_chance*0,12))',
    rankPercents: { ...DEFAULT_RANK_PERCENTS },
  };
  return acc;
}, {} as Record<string, { baseFormula: string; rankPercents: Record<string, number> }>);
